/* Flatten the county maps into jurisdiction records. Built once at
   module load rather than stored as literals, so adding a ZIP is a
   one-line change and the code basis can never drift between entries
   in the same state. */
function buildMarketJurisdictions() {
  const out = {};
  const add = (zip, city, county, state) => {
    const dept = COUNTY_DEPARTMENTS[county] || null;
    /* Keys ending in a letter are disambiguators for towns sharing a
       ZIP with another entry; strip them for the real key. */
    const z = zip.replace(/[a-z]$/, "");
    if (out[z]) return;
    const d = STATE_DEFAULTS[state];
    out[z] = {
      zip: z, city, county, state,
      codeName: d.codeName, codeEdition: d.codeEdition,
      adoption: d.adoption, permit: d.permit,
      inspector: dept
        ? { office: dept.office, phone: dept.phone, address: dept.address,
            web: dept.web, note: dept.note, except: dept.except, checked: dept.checked }
        : { office: "", phone: "", address: "" },
      needsContact: !dept,
      verified: false, sources: d.sources, verifiedDetail: { date: null, by: null },
    };
  };
  Object.entries(OH_COUNTY_ZIPS).forEach(([county, zips]) =>
    Object.entries(zips).forEach(([z, city]) => add(z, city, county, "OH")));
  Object.entries(KY_COUNTY_ZIPS).forEach(([county, zips]) =>
    Object.entries(zips).forEach(([z, city]) => add(z, city, county, "KY")));
  return out;
}
const MARKET_JURISDICTIONS = buildMarketJurisdictions();

function stateForZip(zip) {
  const p = parseInt(String(zip).slice(0, 3), 10);
  if (isNaN(p)) return null;
  const hit = ZIP_PREFIX_STATE.find((r) => p >= r.lo && p <= r.hi);
  return hit ? hit.state : null;
}
/* Returns { ...record, precision } — "verified" | "state" | null */
/* Office-verified inspector contacts, saved from the Code lookup
   screen. Held at module scope so every caller sees the same data
   without threading it through a dozen components; the app hydrates it
   from company settings on load. */
let JURIS_OVERRIDES = {};
function setJurisOverrides(map) { JURIS_OVERRIDES = map || {}; }

/* ZIPs looked up on demand and saved, so the database grows with use
   rather than needing every ZIP in the country shipped up front. */
let LEARNED_JURISDICTIONS = {};
function setLearnedJurisdictions(map) { LEARNED_JURISDICTIONS = map || {}; }

function resolveJurisdiction(zip) {
  const z = String(zip || "").trim();
  if (z.length !== 5) return null;
  const ov = JURIS_OVERRIDES[z];
  const exact = JURISDICTIONS[z];
  if (exact) {
    return ov
      ? { ...exact, inspector: { ...exact.inspector, ...ov }, needsContact: false,
          verified: true, verifiedDetail: { date: ov.at || null, by: ov.by || null }, precision: "verified" }
      : { ...exact, precision: "verified" };
  }
  /* Markets we work: city and county are known, code basis is the
     state code, and the permitting office is filled in by the office
     the first time someone calls it. */
  /* ZIPs the app has looked up and saved. Checked after the curated
     lists so a hand-written record always wins. */
  const learned = LEARNED_JURISDICTIONS[z];
  if (learned) {
    return ov
      ? { ...learned, inspector: { ...learned.inspector, ...ov }, needsContact: false,
          verified: true, verifiedDetail: { date: ov.at || null, by: ov.by || null }, precision: "verified" }
      : { ...learned, precision: learned.needsContact ? "learned" : "market" };
  }
  const mkt = MARKET_JURISDICTIONS[z];
  if (mkt) {
    if (ov) {
      return { ...mkt, inspector: { ...mkt.inspector, ...ov }, needsContact: false,
        verified: true, verifiedDetail: { date: ov.at || null, by: ov.by || null }, precision: "verified" };
    }
    return { ...mkt, precision: "market" };
  }
  const st = stateForZip(z);
  if (!st) return null;
  const d = STATE_DEFAULTS[st];
  return {
    zip: z, city: "", county: "", state: st,
    codeName: d.codeName, codeEdition: d.codeEdition, adoption: d.adoption, permit: d.permit,
    inspector: { office: "Local building department — not yet on file", phone: "", address: "" },
    verified: false, sources: d.sources, verifiedDetail: { date: null, by: null },
    precision: "state",
  };
}

/* Geoapify — address autocomplete + reverse geocoding.
   Free tier: 3,000 requests/day, commercial use permitted, no attribution
   required, results may be stored. Swap the key for an env var at deploy
   and lock it to your domain under Allowed Origins in the Geoapify console. */
const GEO_PROVIDER = {
  name: "geoapify",
  apiKey: (typeof window !== "undefined" && window.__GEOAPIFY_KEY__) || "d4895cd9d44b4229af2885ffa85e343e",
  base: "https://api.geoapify.com/v1/geocode",
  countries: "us",
};
const geoReady = () => !!(GEO_PROVIDER.apiKey && GEO_PROVIDER.name === "geoapify");

/* Type-ahead address suggestions. Returns [] on any failure so the form
   always stays usable — a dead API must never block writing a lead. */
async function geoAutocomplete(text, signal) {
  if (!geoReady() || !text || text.trim().length < 3) return [];
  const url = `${GEO_PROVIDER.base}/autocomplete?text=${encodeURIComponent(text)}`
    + `&filter=countrycode:${GEO_PROVIDER.countries}&limit=6&format=json&apiKey=${GEO_PROVIDER.apiKey}`;
  try {
    const res = await fetch(url, { signal });
    if (!res.ok) return [];
    const data = await res.json();
    return (data.results || []).map((r) => ({
      id: r.place_id || `${r.lat},${r.lon}`,
      formatted: r.formatted || "",
      street: [r.housenumber, r.street].filter(Boolean).join(" ") || r.address_line1 || "",
      city: r.city || r.town || r.village || r.county || "",
      state: r.state_code || "",
      zip: r.postcode || "",
      lat: r.lat, lng: r.lon,
    }));
  } catch { return []; }
}

/* Coordinates -> street address. Used to stamp photos with a real address
   alongside the GPS fix. */
async function geoReverse(lat, lng) {
  if (!geoReady() || lat == null || lng == null) return null;
  const url = `${GEO_PROVIDER.base}/reverse?lat=${lat}&lon=${lng}&format=json&apiKey=${GEO_PROVIDER.apiKey}`;
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    const r = (data.results || [])[0];
    if (!r) return null;
    return {
      formatted: r.formatted || "",
      street: [r.housenumber, r.street].filter(Boolean).join(" ") || r.address_line1 || "",
      city: r.city || r.town || r.village || "",
      state: r.state_code || "",
      zip: r.postcode || "",
    };
  } catch { return null; }
}

/* Look up a ZIP we have never seen. Geoapify returns the county, which
   is the piece that matters: departments are keyed by county, so a new
   ZIP inside a county already on file resolves completely — office,
   phone, address and all — without anyone typing a thing. A ZIP in a
   new county resolves to city, county and the correct state code
   basis, leaving only the permitting office for a human to add. */
async function geoLookupZip(zip) {
  const z = String(zip || "").trim();
  if (!geoReady() || z.length !== 5) return null;
  const url = `${GEO_PROVIDER.base}/search?postcode=${encodeURIComponent(z)}`
    + `&filter=countrycode:${GEO_PROVIDER.countries}&type=postcode&limit=1&format=json&apiKey=${GEO_PROVIDER.apiKey}`;
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    const r = (data.results || [])[0];
    if (!r) return null;
    const state = r.state_code || "";
    if (!STATE_DEFAULTS[state]) {
      /* Outside the three states we hold code data for. Honest failure
         is better than presenting an Ohio code basis for an Indiana
         address. */
      return { unsupported: true, state, city: r.city || "", county: r.county || "" };
    }
    /* Geoapify returns "Hamilton County" or sometimes "Hamilton"; both
       are normalised so the department map matches either way. */
    const rawCounty = r.county || "";
    const county = rawCounty && !/county$/i.test(rawCounty) ? `${rawCounty} County` : rawCounty;
    return {
      zip: z, city: r.city || r.town || r.village || "", county, state,
      dept: COUNTY_DEPARTMENTS[county] || null,
    };
  } catch { return null; }
}

/* Build a jurisdiction record from a lookup result, ready to save. */
function jurisdictionFromLookup(hit) {
  const d = STATE_DEFAULTS[hit.state];
  const dept = hit.dept;
  return {
    zip: hit.zip, city: hit.city, county: hit.county, state: hit.state,
    codeName: d.codeName, codeEdition: d.codeEdition, adoption: d.adoption, permit: d.permit,
    inspector: dept
      ? { office: dept.office, phone: dept.phone, address: dept.address,
          web: dept.web, note: dept.note, except: dept.except, checked: dept.checked }
      : { office: "", phone: "", address: "" },
    needsContact: !dept,
    verified: false, sources: d.sources, verifiedDetail: { date: null, by: null },
  };
}

function captureLocation() {
  return new Promise((resolve) => {
    if (typeof navigator === "undefined" || !navigator.geolocation) {
      resolve({ ok: false, reason: "Geolocation not supported on this device." });
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({
        ok: true,
        lat: +pos.coords.latitude.toFixed(6),
        lng: +pos.coords.longitude.toFixed(6),
        accuracy: Math.round(pos.coords.accuracy),
        at: new Date().toISOString(),
      }),
      (err) => resolve({ ok: false, reason: err.code === 1 ? "Location permission denied." : "Could not get a location fix." }),
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  });
}
const fmtCoord = (lat, lng) => `${lat.toFixed(5)}, ${lng.toFixed(5)}`;
/* Provider-neutral links — work with no API key, open in the user's map app. */
const mapLinkForCoords = (lat, lng) => `https://www.google.com/maps/search/?api=1&query=${lat},${lng}`;
const mapLinkForAddress = (addr) => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(addr)}`;
const directionsLink = (addr) => `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(addr)}`;
const staticMapEmbed = (lat, lng) => {
  const d = 0.004;
  return `https://www.openstreetmap.org/export/embed.html?bbox=${lng - d}%2C${lat - d}%2C${lng + d}%2C${lat + d}&layer=mapnik&marker=${lat}%2C${lng}`;
};
const fmtStamp = (iso) => {
  try {
    return new Date(iso).toLocaleString(undefined, {
      month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit",
    });
  } catch { return iso; }
};

const money = (n) =>
  (n < 0 ? "-$" : "$") + Math.abs(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const pct1 = (n) => `${n.toFixed(2)}%`;

/* Phone display, in the house format: 1(555)555-5555.
   Anything that is not ten or eleven digits is left exactly as typed —
   extensions, international numbers and half-entered values should not
   be mangled into something that looks valid and is not. */
function fmtPhone(v) {
  const d = String(v || "").replace(/\D/g, "");
  if (d.length === 10) return `1(${d.slice(0, 3)})${d.slice(3, 6)}-${d.slice(6)}`;
  if (d.length === 11 && d[0] === "1") return `1(${d.slice(1, 4)})${d.slice(4, 7)}-${d.slice(7)}`;
  return String(v || "");
}
/* Digits only, for tel: links. */
const telHref = (v) => `tel:${String(v || "").replace(/\D/g, "")}`;

/* Quantity x price, shown the way an invoice line reads. Kept here so
   estimates, change orders and material lines all agree. */
const lineTotal = (qty, price) => num(qty) * num(price);
const qtyFmt = (n) => {
  const v = num(n);
  return Number.isInteger(v) ? String(v) : v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const uid = (p) => p + Math.random().toString(36).slice(2, 8);
const nowStamp = () =>
  new Date().toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });

function estimateTotal(est) {
  return est.items.reduce((s, it) => s + num(it.qty) * num(it.price), 0);
}
/* Turn an accepted estimate into a contract: copy the total, the scope and the
   accepted line items across as structured data (not a re-typed price). Invoice
   and A/R then follow automatically via paymentsSummary, which reads the
   contract price. Preserves an already-signed contract untouched. */
function convertEstimateToContract(job) {
  const est = job.estimate || {};
  const con = job.contract || mkContract();
  if (con.status === "Signed") return con;
  return {
    ...con,
    number: con.number || `CON-${new Date().getFullYear()}-${String(Math.floor(Math.random() * 900) + 100)}`,
    price: estimateTotal(est),
    scope: con.scope || (est.scope || `Per accepted estimate ${est.number || ""}`.trim()),
    items: (est.items || []).map((it) => ({ id: it.id || uid("ci"), desc: it.desc, qty: it.qty, unit: it.unit, price: num(it.price) })),
    status: con.status === "Not started" || !con.status ? "Ready to sign" : con.status,
    fromEstimate: est.number || true,
  };
}
function computeFin(fin) {
  const sum = (a) => a.reduce((s, x) => s + x.amt, 0);
  const materials = sum(fin.materials), labor = sum(fin.labor), other = sum(fin.other);
  return { materials, labor, other, cogs: materials + labor + other };
}
/* Commission structures — merged from the Ridgeline repo. Structure choice is
   admin-only; reps see the resulting numbers, never the lever. Defaults to
   "grossProfit" (rate% of gross) so existing jobs behave exactly as before. */
const STRUCTURES = [
  { id: "grossProfit", label: "Gross Profit", usesRate: true, usesOverhead: false,
    blurb: "Rate % of (contract − COGS). No overhead allocation before the split." },
  { id: "netProfit", label: "Net Profit", usesRate: true, usesOverhead: true,
    blurb: "Rate % of (contract − COGS − overhead allocation). Overhead % of contract is set below." },
  { id: "tenFiftyFifty", label: "10 / 50 / 50", usesRate: false, usesOverhead: false,
    blurb: "10% of contract off the top to company overhead, then remaining profit split 50/50 rep and company." },
  { id: "grossContract", label: "Gross Contract", usesRate: true, usesOverhead: false,
    blurb: "Rate % of total contract value, regardless of job cost." },
];
/* Who is on a job, and for what share of the commission.
   Older jobs carry a single `assignee` string; they normalise to one
   rep at 100% so nothing has to be migrated. The first entry is the
   primary rep — the one shown on the board, the portal and reports. */
function jobReps(job) {
  const list = Array.isArray(job && job.reps) ? job.reps.filter((r) => r && r.name) : [];
  if (list.length) {
    return list.map((r) => ({ name: r.name, split: Number(r.split) || 0 }));
  }
  return job && job.assignee ? [{ name: job.assignee, split: 100 }] : [];
}
function repSplitTotal(job) {
  return jobReps(job).reduce((a, r) => a + (Number(r.split) || 0), 0);
}
/* Splits are validated rather than silently normalised. Quietly
   rescaling 60/60 to 50/50 would pay someone a number they never
   agreed to; the UI flags it and the cap-out refuses to look settled. */
function repSplitValid(job) {
  const reps = jobReps(job);
  if (!reps.length) return true;
  return Math.abs(repSplitTotal(job) - 100) < 0.01;
}

function computeCapOut(job) {
  const { materials, labor, other, cogs } = computeFin(job.fin);
  /* Approved change orders move the contract. Leaving them out is the
     most common way a job reads profitable and is not. */
  const coApproved = (Array.isArray(job.changeOrders) ? job.changeOrders : [])
    .filter((c) => c.status === "Approved").reduce((a2, c) => a2 + coTotal(c), 0);
  const contract = (job.contract.price || estimateTotal(job.estimate) || job.value || 0) + coApproved;
  const gross = contract - cogs;
  const structure = job.fin.structure || "grossProfit";
  const rate = job.fin.commissionRate;
  const overheadPct = job.fin.overheadPct ?? 10;
  const overheadAlloc = contract * (overheadPct / 100);
  const net = gross - overheadAlloc;

  let commission = 0, base = 0, baseLabel = "";
  if (structure === "netProfit") {
    base = net; baseLabel = "Net profit";
    commission = Math.max(0, net) * (rate / 100);
  } else if (structure === "tenFiftyFifty") {
    const top = contract * 0.10;
    const remaining = gross - top;
    base = remaining; baseLabel = "Profit after 10% overhead";
    commission = Math.max(0, remaining) * 0.5;
  } else if (structure === "grossContract") {
    base = contract; baseLabel = "Contract value";
    commission = contract * (rate / 100);
  } else {
    base = gross; baseLabel = "Gross profit";
    commission = Math.max(0, gross) * (rate / 100);
  }
  const netCompany = gross - commission;
  /* Reimbursements come from two places now:
     - cost lines flagged reimbursable (matches the cap-out sheet, where
       each Jacob-paid line is marked Yes in the Reimbursement column), and
     - the standalone reimbursements list (kept for back-compat).
     A flagged line's "status" of "Needs paid" means a vendor is still
     owed — it is a reimbursement to whoever fronted it, and it is
     surfaced separately so nothing owed slips through. */
  const flagged = [...job.fin.materials, ...job.fin.labor, ...job.fin.other].filter((l) => l.reimburse);
  const flaggedTotal = flagged.reduce((s, l) => s + num(l.amt), 0);
  const listTotal = (job.fin.reimbursements || []).reduce((s, r) => s + num(r.amt), 0);
  const reimbTotal = flaggedTotal + listTotal;
  const needsPaid = [
    ...flagged.filter((l) => l.status === "Needs paid"),
    ...(job.fin.reimbursements || []).filter((r) => r.status === "Needs paid"),
  ];
  const needsPaidTotal = needsPaid.reduce((s, l) => s + num(l.amt), 0);
  /* Multi-rep jobs split the pool, they do not each earn their own
     rate on it. That keeps the company's total commission identical
     whether one rep or three worked the job — the alternative makes
     cost swing with staffing, which is how a job quietly goes upside
     down. */
  const reps = jobReps(job);
  const splitsOk = repSplitValid(job);
  const repShares = reps.map((r) => ({
    name: r.name,
    split: r.split,
    amount: commission * ((Number(r.split) || 0) / 100),
  }));

  return {
    contract, materials, labor, other, cogs, gross,
    grossMargin: contract ? (gross / contract) * 100 : 0,
    structure, base, baseLabel, overheadAlloc, overheadPct,
    commission, netCompany, reps, repShares, splitsOk,
    splitTotal: repSplitTotal(job),
    repPctGross: gross > 0 ? (commission / gross) * 100 : 0,
    coPctGross: gross > 0 ? (netCompany / gross) * 100 : 0,
    repPctJob: contract ? (commission / contract) * 100 : 0,
    coPctJob: contract ? (netCompany / contract) * 100 : 0,
    reimbTotal, flaggedTotal, listTotal, needsPaid, needsPaidTotal,
    payout: commission + reimbTotal,
  };
}
/* Same job under every structure — admin-only what-if comparison. */
function compareStructures(job) {
  return STRUCTURES.map((st) => {
    const c = computeCapOut({ ...job, fin: { ...job.fin, structure: st.id } });
    return { id: st.id, label: st.label, commission: c.commission, netCompany: c.netCompany };
  });
}
function paymentsSummary(job) {
  const received = job.payments.filter((p) => p.type === "Received").reduce((s, p) => s + p.amt, 0);
  const paidOut = job.payments.filter((p) => p.type !== "Received").reduce((s, p) => s + p.amt, 0);
  const coApproved = (Array.isArray(job.changeOrders) ? job.changeOrders : [])
    .filter((c) => c.status === "Approved").reduce((a2, c) => a2 + coTotal(c), 0);
  const contract = (job.contract.price || estimateTotal(job.estimate) || job.value || 0) + coApproved;
  return { received, paidOut, contract, balance: contract - received };
}
/* Export gate. Reps cannot pull data out — this is what stops a
   departing salesperson from walking off with the book of business.
   The company owns the data. Admins export freely. Flipped by the app
   once the signed-in seat is known; defaults closed so a rep can never
   export during the brief window before it is set. Every blocked and
   allowed export is recorded through exportLogger. */
let EXPORT_ALLOWED = false;
let exportLogger = () => {};
function setExportPolicy(isAdmin, logger) {
  EXPORT_ALLOWED = !!isAdmin;
  if (logger) exportLogger = logger;
}
function downloadCsv(name, rows) {
  if (!EXPORT_ALLOWED) {
    try { exportLogger({ type: "export_blocked", text: `Blocked data export attempt: ${name}`, rule: "export_attempts" }); } catch (e) {}
    if (typeof window !== "undefined" && window.alert) {
      window.alert("Exporting data is restricted to admins. The company owns this data.");
    }
    return false;
  }
  try { exportLogger({ type: "export", text: `Exported ${name}` }); } catch (e) {}
  try {
    const csv = rows.map((r) => r.map((c) => `"${String(c ?? "").replaceAll('"', '""')}"`).join(",")).join("\n");
    const blob = new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob); a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 2000);
    return true;
  } catch (e) {
    /* Sandboxed previews block programmatic downloads; the deployed site allows them. */
    if (typeof window !== "undefined" && window.alert) window.alert("Download blocked in this preview. On the deployed site this saves a file.");
    return false;
  }
}
function jurisdictionForZip(zip) { return resolveJurisdiction(zip); }
function citeFor(state, topic) {
  return (CODE_PROVISIONS[state] && CODE_PROVISIONS[state][topic]) || CODE_PROVISIONS.OH[topic];
}

/* Material list generator — quantities from measurements + waste. */
function generateRoofingMaterials(m) {
  if (!num(m.squares)) return null;
  const sq = num(m.squares) * (1 + num(m.waste) / 100);
  const lfEavesRakes = num(m.eaves) + num(m.rakes);
  return [
    { item: "Architectural shingles", qty: Math.ceil(sq * 3), unit: "bundles", note: `${sq.toFixed(1)} SQ incl. ${m.waste}% waste` },
    { item: "Hip & ridge cap", qty: Math.max(1, Math.ceil((num(m.ridges) + num(m.hips)) / 25)), unit: "bundles", note: `${num(m.ridges) + num(m.hips)} LF ridge + hip` },
    { item: "Starter strip", qty: Math.max(1, Math.ceil(lfEavesRakes / 105)), unit: "rolls", note: `${lfEavesRakes} LF eaves + rakes` },
    { item: "Synthetic underlayment", qty: Math.max(1, Math.ceil(sq / 10)), unit: "rolls", note: "10 SQ per roll" },
    { item: "Ice & water shield", qty: Math.max(1, Math.ceil((num(m.eaves) + num(m.valleys)) / 65)), unit: "rolls", note: `${num(m.eaves) + num(m.valleys)} LF eaves + valleys` },
    { item: "Drip edge (10 ft sticks)", qty: Math.ceil(lfEavesRakes / 10), unit: "sticks", note: `${lfEavesRakes} LF` },
    { item: "Ridge vent", qty: Math.ceil(num(m.ridges) / 4), unit: "4 ft sections", note: `${m.ridges} LF ridge` },
    { item: "Step flashing", qty: Math.ceil(num(m.stepFlash) * 1.4), unit: "pieces", note: `${m.stepFlash} LF` },
    { item: "Pipe jacks", qty: num(m.penetrations), unit: "each", note: "one per penetration" },
    { item: "Coil nails 1-1/4 in.", qty: Math.max(1, Math.ceil(sq / 18)), unit: "boxes", note: "about 18 SQ per box" },
    { item: "Cap nails", qty: Math.max(1, Math.ceil(sq / 30)), unit: "boxes", note: "underlayment fastening" },
  ];
}

/* Total squares of material actually going on the roof — field shingles plus
   ridge/hip cap and starter, each at three units per square (e.g. 5 cap
   bundles = 1.66 sq, 2 starter = 0.66 sq, 66 shingle bundles = 22 sq → 24.3
   sq). Returns the per-line breakdown and the total so the work order can show
   its work, and so a sub's pay can be figured off installed squares. */
const WO_COVERAGE_PER_UNIT = {
  "Architectural shingles": 1 / 3,
  "Hip & ridge cap": 1 / 3,
  "Starter strip": 1 / 3,
};
function installedSquares(mats) {
  if (!mats) return null;
  const lines = mats
    .map((x) => ({ item: x.item, qty: x.qty, unit: x.unit, sq: (WO_COVERAGE_PER_UNIT[x.item] || 0) * x.qty }))
    .filter((l) => l.sq > 0);
  const total = lines.reduce((a, l) => a + l.sq, 0);
  return { lines, total: Math.round(total * 100) / 100 };
}

/* Map a free-text price-sheet row to a known pay code, so an uploaded
   subcontractor sheet drives pay automatically. Anything unrecognized is
   kept as a flat add-on. */
function subCodeFor(text) {
  const s = String(text || "").toLowerCase();
  /* Order matters: a base install line often names a pitch range
     ("install, 2/12 to 8/12 pitch") — it must NOT be read as a steep
     charge. Match the explicit steep/mansard and tear-off wording first,
     then the base install, then a bare "steep/pitch" as a last resort. */
  if (/mansard|steep\s*charge/.test(s)) return "steep_per_square";
  if (/additional layer|layer removal|tear|\brip\b/.test(s)) return "tearoff_per_square";
  if (/(3|three|3\+).*stor/.test(s)) return "story_3";
  if (/(2|two|second).*stor/.test(s)) return "story_2";
  if (/chimney/.test(s)) {
    if (/small/.test(s)) return "chimney_small";
    if (/large/.test(s)) return "chimney_large";
    return "chimney_medium";
  }
  if (/install/.test(s) && /(shingle|roof)/.test(s)) return "per_square";
  if (/steep|pitch/.test(s)) return "steep_per_square";
  return null;
}
const SUB_RATE_LABELS = {
  per_square: "Install (per square)", steep_per_square: "Steep charge (per square)",
  tearoff_per_square: "Tear-off (per square, per extra layer)", story_2: "2-story adder",
  story_3: "3+ story adder", chimney_small: "Chimney — small", chimney_medium: "Chimney — medium",
  chimney_large: "Chimney — large",
};
function subRate(crew, code) {
  const row = ((crew && crew.rateCard) || []).find((r) => r.code === code);
  return row ? num(row.price) : 0;
}
/* Figure a subcontractor's pay for a job from their uploaded rate card and
   the job's installed squares + conditions. Returns a transparent line
   breakdown so the office can see exactly how the number was built. */
function computeSubPay(job, crew) {
  if (!crew || !((crew.rateCard || []).length)) return null;
  const cov = installedSquares(generateRoofingMaterials(job.measurements));
  const sq = cov ? cov.total : 0;
  const wo = job.workOrder || {};
  const lines = [];
  const per = subRate(crew, "per_square");
  if (per && sq) lines.push({ label: `Install ${sq} sq @ ${money(per)}/sq`, amt: per * sq });
  if (wo.steep) { const s = subRate(crew, "steep_per_square"); if (s && sq) lines.push({ label: `Steep ${sq} sq @ ${money(s)}/sq`, amt: s * sq }); }
  const layers = parseInt(wo.layers || job.checklist.layers, 10) || 1;
  if (layers > 1) { const t = subRate(crew, "tearoff_per_square"); if (t && sq) lines.push({ label: `Tear-off ${layers} layers, ${sq} sq @ ${money(t)}/sq`, amt: t * sq * (layers - 1) }); }
  if (wo.stories === "2") { const a = subRate(crew, "story_2"); if (a) lines.push({ label: "2-story adder", amt: a }); }
  if (wo.stories === "3+") { const a = subRate(crew, "story_3"); if (a) lines.push({ label: "3+ story adder", amt: a }); }
  const chim = (wo.chimney || {}).size;
  if (chim && chim !== "none") { const a = subRate(crew, `chimney_${chim}`); if (a) lines.push({ label: `Chimney flashing (${chim})`, amt: a }); }
  const total = lines.reduce((a, l) => a + l.amt, 0);
  return { lines, total: Math.round(total * 100) / 100, squares: sq };
}

/* ================================================================
   AUTH ADAPTER
   When the app is deployed with Supabase credentials, src/main.jsx
   puts a real auth client on window.__AUTH__ and everything below
   runs against it. With no backend present the app falls back to the
   demo account picker so it still previews and demos.
   ================================================================ */
const AUTH = () => (typeof window !== "undefined" ? window.__AUTH__ : null);
const liveAuth = () => !!AUTH();
/* Map a database profile row onto the shape the UI already uses. */
const fromProfile = (row) => ({
  id: row.id, name: row.name, email: row.email, phone: row.phone || "",
  role: row.role, title: row.title || "", active: row.active,
  commissionRate: row.commission_rate != null ? Number(row.commission_rate) : 60,
  addedAt: row.added_at || "", tenantId: row.tenant_id || null,
});
const toProfile = (u) => ({
  name: u.name, email: u.email, phone: u.phone || null, role: u.role,
  title: u.title || null, commission_rate: u.commissionRate ?? 60, active: u.active,
});

/* ================================================================
   SHARED UI
   ================================================================ */
const S = { ink: "#111827", sub: "#6B7280", line: "#E5E7EB", bg: "#F7F8FA", soft: "#F3F4F6" };
/* Live theme. The root component copies brand colors in on every render,
   and because inline styles read these properties at render time, a color
   change in Branding repaints the whole app immediately. */
const T = { primary: "#20242A", accent: "#0A9E98", accentSoft: "#E3F5F4" };
function softOf(hex) {
  try {
    const n = parseInt(hex.slice(1), 16);
    const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    const mix = (c) => Math.round(c + (255 - c) * 0.88);
    return `rgb(${mix(r)}, ${mix(g)}, ${mix(b)})`;
  } catch { return "#EAF2FD"; }
}

/* Donut chart — pure CSS conic-gradient, no charting library. Built
   for proportion-of-a-whole breakdowns (revenue by source, job cost
   mix) where a ranked list alone doesn't give an at-a-glance sense of
   share. Deliberately paired with the underlying numbers wherever it's
   used, never standing alone — a donut answers "roughly what share,"
   a table answers "exactly how much"; people need both. */
function DonutChart({ data, size = 132, thickness = 18, centerLabel, centerValue }) {
  const total = data.reduce((s, d) => s + Math.max(0, d.value), 0);
  let acc = 0;
  const stops = data.map((d) => {
    const pct = total > 0 ? (Math.max(0, d.value) / total) * 100 : 0;
    const start = acc;
    acc += pct;
    return `${d.color} ${start}% ${acc}%`;
  });
  const gradient = total > 0 && stops.length
    ? `conic-gradient(${stops.join(", ")})`
    : `conic-gradient(${S.line} 0% 100%)`;
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 18, flexWrap: "wrap" }}>
      <div style={{
        position: "relative", width: size, height: size, borderRadius: "50%",
        background: gradient, flexShrink: 0,
      }}>
        <div style={{
          position: "absolute", inset: thickness, borderRadius: "50%", background: "#fff",
          display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
        }}>
          {centerValue != null && <div style={{ fontSize: 15, fontWeight: 800, color: S.ink }}>{centerValue}</div>}
          {centerLabel && <div style={{ fontSize: 10, color: S.sub, textAlign: "center", lineHeight: 1.3 }}>{centerLabel}</div>}
        </div>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 6, minWidth: 0, flex: 1 }}>
        {data.map((d) => {
          const pct = total > 0 ? Math.round((Math.max(0, d.value) / total) * 100) : 0;
          return (
            <div key={d.label} style={{ display: "flex", alignItems: "center", gap: 7, fontSize: 12.5 }}>
              <span style={{ width: 9, height: 9, borderRadius: 3, background: d.color, flexShrink: 0 }} />
              <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", color: S.ink, flex: 1 }}>{d.label}</span>
              <span style={{ color: S.sub, fontWeight: 700, flexShrink: 0 }}>{pct}%</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
/* A small fixed palette so charts stay visually consistent everywhere
   they're used, rather than each call site inventing its own colors. */
const DONUT_PALETTE = ["#0A9E98", "#1B6DE0", "#F59E0B", "#7C3AED", "#EC4899", "#177245", "#B42318", "#5B6470"];

function Chip({ children, tone = "gray" }) {
  const tones = {
    gray: { bg: "#F3F4F6", fg: "#374151" },
    blue: { bg: T.accentSoft, fg: T.accent },
    green: { bg: "#E8F6EE", fg: "#177245" },
    red: { bg: "#FDECEC", fg: "#B42318" },
    amber: { bg: "#FDF4E3", fg: "#92600A" },
    slate: { bg: "#E9EDEF", fg: T.primary },
  };
  const t = tones[tone] || tones.gray;
  return (
    <span style={{
      background: t.bg, color: t.fg, fontSize: 12, fontWeight: 600,
      padding: "3px 10px", borderRadius: 999, whiteSpace: "nowrap", display: "inline-block",
      alignSelf: "flex-start", flexShrink: 0,
    }}>{children}</span>
  );
}

function Btn({ children, kind = "primary", onClick, style, small, disabled, ...props }) {
  const base = {
    display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8,
    border: "1px solid transparent", borderRadius: 10, cursor: disabled ? "not-allowed" : "pointer",
    fontWeight: 600, fontSize: small ? 13 : 15,
    padding: small ? "7px 12px" : "11px 18px",
    opacity: disabled ? 0.5 : 1,
  };
  const kinds = {
    primary: { background: T.accent, color: "#fff" },
    dark: { background: T.primary, color: "#fff" },
    ghost: { background: "#fff", color: S.ink, border: `1px solid ${S.line}` },
    soft: { background: T.accentSoft, color: T.accent },
    danger: { background: "#fff", color: "#B42318", border: `1px solid ${S.line}` },
    green: { background: "#177245", color: "#fff" },
  };
  return (
    <button {...props} disabled={disabled} onClick={disabled ? undefined : onClick} style={{ ...base, ...kinds[kind], ...style }}>
      {children}
    </button>
  );
}

function Field({ label, children, hint }) {
  return (
    <label style={{ display: "block", marginBottom: 14 }}>
      <div style={{ fontSize: 13, fontWeight: 600, color: S.ink, marginBottom: 6 }}>{label}</div>
      {children}
      {hint && <div style={{ fontSize: 12, color: S.sub, marginTop: 5 }}>{hint}</div>}
    </label>
  );
}
const inputStyle = {
  width: "100%", boxSizing: "border-box", padding: "11px 13px", fontSize: 15,
  border: `1px solid ${S.line}`, borderRadius: 10, background: "#fff", color: S.ink, outline: "none",
  fontFamily: "inherit",
};
const selStyle = { ...inputStyle, appearance: "auto" };
/* iOS renders type=date taller than a text input and ignores a fixed
   height, which overlapped the neighbouring field. Neutralising the
   native appearance and using minHeight keeps it in its column. */
const dateInputStyle = {
  ...inputStyle, WebkitAppearance: "none", MozAppearance: "none", appearance: "none",
  minHeight: 44, boxSizing: "border-box", width: "100%", minWidth: 0,
};

function Card({ children, style, pad = 18, onClick }) {
  return (
    <div onClick={onClick} style={{ background: "#fff", border: `1px solid ${S.line}`, borderRadius: 14, padding: pad, ...style }}>
      {children}
    </div>
  );
}
function CardTitle({ children, right }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
      <div style={{ fontSize: 15, fontWeight: 700, color: S.ink }}>{children}</div>
      {right}
    </div>
  );
}
function KV({ k, v, strong }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", gap: 12, padding: "7px 0" }}>
      <span style={{ fontSize: 13, color: S.sub }}>{k}</span>
      <span style={{ fontSize: 13, fontWeight: strong ? 800 : 600, color: S.ink, textAlign: "right" }}>{v}</span>
    </div>
  );
}

/* Merged from the Ridgeline repo. */
function Callout({ label, children, tone = "amber" }) {
  const map = {
    amber: ["#FDF4E3", "#92600A"], red: ["#FDECEC", "#B42318"], green: ["#E8F6EE", "#177245"],
  };
  const [bg, fg] = map[tone] || map.amber;
  return (
    <div style={{ background: bg, borderLeft: `3px solid ${fg}`, borderRadius: 8, padding: "12px 14px", marginTop: 12 }}>
      {label && <div style={{ fontSize: 13, fontWeight: 800, color: fg, marginBottom: 6 }}>{label}</div>}
      <div style={{ fontSize: 14, color: S.ink, lineHeight: 1.55 }}>{children}</div>
    </div>
  );
}
function Bullets({ items }) {
  return (
    <ul style={{ margin: "6px 0 0", paddingLeft: 18 }}>
      {items.map((t, i) => (
        <li key={i} style={{ fontSize: 14, color: S.ink, lineHeight: 1.55, marginBottom: 6 }}>{t}</li>
      ))}
    </ul>
  );
}
function SourceLink({ srcId }) {
  const s = SOURCES[srcId];
  if (!s) return null;
  return (
    <a href={s.url} target="_blank" rel="noreferrer" style={{
      display: "inline-flex", alignItems: "center", gap: 6, textDecoration: "none",
      border: `1px solid ${S.line}`, borderRadius: 999, padding: "6px 12px",
      fontSize: 12.5, fontWeight: 700, color: T.accent, background: "#fff", marginTop: 8, marginRight: 8,
    }}>
      <ExternalLink size={13} /> {s.name}
    </a>
  );
}

/* ================================================================
   ADDRESS AUTOCOMPLETE — debounced Geoapify typeahead.
   Degrades to a plain text field if the API is unreachable, so a
   lead can always be written.
   ================================================================ */
function AddressAutocomplete({ value, onChange, onPick, placeholder }) {
  const [items, setItems] = useState([]);
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [hi, setHi] = useState(-1);
  const abortRef = useRef(null);
  const timerRef = useRef(null);
  const blurRef = useRef(null);

  useEffect(() => () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    if (abortRef.current) abortRef.current.abort();
    if (blurRef.current) clearTimeout(blurRef.current);
  }, []);

  const query = (text) => {
    if (timerRef.current) clearTimeout(timerRef.current);
    if (!geoReady() || text.trim().length < 3) { setItems([]); setOpen(false); return; }
    timerRef.current = setTimeout(async () => {
      if (abortRef.current) abortRef.current.abort();
      const ctl = new AbortController();
      abortRef.current = ctl;
      setBusy(true);
      const res = await geoAutocomplete(text, ctl.signal);
      setBusy(false);
      setItems(res); setHi(-1);
      setOpen(res.length > 0);
    }, 280);
  };

  const choose = (it) => {
    setOpen(false); setItems([]);
    onPick(it);
  };

  return (
    <div style={{ position: "relative" }}>
      <div style={{ position: "relative" }}>
        <input
          style={{ ...inputStyle, paddingRight: 36 }}
          value={value}
          placeholder={placeholder}
          autoComplete="off"
          onChange={(e) => { onChange(e.target.value); query(e.target.value); }}
          onFocus={() => items.length && setOpen(true)}
          onBlur={() => { blurRef.current = setTimeout(() => setOpen(false), 160); }}
          onKeyDown={(e) => {
            if (!open || !items.length) return;
            if (e.key === "ArrowDown") { e.preventDefault(); setHi((h) => (h + 1) % items.length); }
            else if (e.key === "ArrowUp") { e.preventDefault(); setHi((h) => (h - 1 + items.length) % items.length); }
            else if (e.key === "Enter" && hi >= 0) { e.preventDefault(); choose(items[hi]); }
            else if (e.key === "Escape") setOpen(false);
          }}
        />
        <span style={{ position: "absolute", right: 11, top: "50%", transform: "translateY(-50%)", display: "flex" }}>
          {busy ? <RefreshCw size={15} color="#9CA3AF" /> : <MapPin size={15} color="#C7CBD1" />}
        </span>
      </div>
      {open && items.length > 0 && (
        <div style={{
          position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0, zIndex: 30,
          background: "#fff", border: `1px solid ${S.line}`, borderRadius: 12,
          boxShadow: "0 10px 28px rgba(17,24,39,.14)", overflow: "hidden", maxHeight: 260, overflowY: "auto",
        }}>
          {items.map((it, i) => (
            <button key={it.id} type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => choose(it)}
              onMouseEnter={() => setHi(i)}
              style={{
                display: "flex", alignItems: "flex-start", gap: 10, width: "100%", textAlign: "left",
                border: "none", cursor: "pointer", padding: "11px 13px",
                background: hi === i ? T.accentSoft : "#fff",
                borderTop: i ? `1px solid ${S.line}` : "none",
              }}>
              <MapPin size={14} color={T.accent} style={{ flexShrink: 0, marginTop: 2 }} />
              <span style={{ flex: 1, minWidth: 0 }}>
                <span style={{ display: "block", fontSize: 14, fontWeight: 600, color: S.ink }}>
                  {it.street || it.formatted}
                </span>
                <span style={{ display: "block", fontSize: 12, color: S.sub, marginTop: 2 }}>
                  {[it.city, it.state, it.zip].filter(Boolean).join(", ")}
                </span>
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function Sheet({ open, onClose, title, children, footer, wide }) {
  if (!open) return null;
  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 60, background: "rgba(17,24,39,.45)",
      display: "flex", alignItems: "flex-end", justifyContent: "center",
    }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: "#fff", width: "100%", maxWidth: wide ? 760 : 560, maxHeight: "90vh",
        borderRadius: "18px 18px 0 0", display: "flex", flexDirection: "column",
      }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "18px 20px 12px" }}>
          <div style={{ fontSize: 20, fontWeight: 700, color: S.ink }}>{title}</div>
          <button onClick={onClose} style={{
            border: "none", background: "#F3F4F6", borderRadius: 999, width: 34, height: 34,
            display: "grid", placeItems: "center", cursor: "pointer",
          }}><X size={17} /></button>
        </div>
        <div style={{ overflowY: "auto", padding: "4px 20px 20px", flex: 1 }}>{children}</div>
        {footer && <div style={{ padding: "12px 20px 20px", borderTop: `1px solid ${S.line}` }}>{footer}</div>}
      </div>
    </div>
  );
}

function Toast({ msg }) {
  if (!msg) return null;
  return (
    <div style={{
      position: "fixed", bottom: 96, left: "50%", transform: "translateX(-50%)",
      background: "#111827", color: "#fff", borderRadius: 999, padding: "10px 18px",
      fontSize: 14, fontWeight: 600, zIndex: 90, whiteSpace: "nowrap",
    }}>{msg}</div>
  );
}

/* ================================================================
   SIGNATURE PAD — canvas capture, stored as data URL with timestamp
   ================================================================ */
function SignaturePad({ open, onClose, title, onApply }) {
  const ref = useRef(null);
  const drawing = useRef(false);
  const dirty = useRef(false);
  useEffect(() => {
    if (!open) return;
    const cv = ref.current;
    if (!cv) return;
    const ctx = cv.getContext("2d");
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, cv.width, cv.height);
    ctx.strokeStyle = "#111827";
    ctx.lineWidth = 2.4;
    ctx.lineCap = "round";
    dirty.current = false;
  }, [open]);
  const pos = (e) => {
    const cv = ref.current, r = cv.getBoundingClientRect();
    const t = e.touches ? e.touches[0] : e;
    return { x: ((t.clientX - r.left) / r.width) * cv.width, y: ((t.clientY - r.top) / r.height) * cv.height };
  };
  const start = (e) => {
    e.preventDefault();
    drawing.current = true;
    const ctx = ref.current.getContext("2d");
    const p = pos(e);
    ctx.beginPath(); ctx.moveTo(p.x, p.y);
  };
  const move = (e) => {
    if (!drawing.current) return;
    e.preventDefault();
    const ctx = ref.current.getContext("2d");
    const p = pos(e);
    ctx.lineTo(p.x, p.y); ctx.stroke();
    dirty.current = true;
  };
  const end = () => { drawing.current = false; };
  const clear = () => {
    const cv = ref.current, ctx = cv.getContext("2d");
    ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, cv.width, cv.height);
    dirty.current = false;
  };
  if (!open) return null;
  return (
    <Sheet open={open} onClose={onClose} title={title}
      footer={
        <div style={{ display: "flex", gap: 10 }}>
          <Btn kind="ghost" style={{ flex: 1 }} onClick={clear}>Clear</Btn>
          <Btn style={{ flex: 2 }} onClick={() => {
            if (!dirty.current) return;
            onApply(ref.current.toDataURL("image/png"), nowStamp());
            onClose();
          }}>Apply signature</Btn>
        </div>
      }>
      <div style={{ fontSize: 14, color: S.sub, marginBottom: 12 }}>
        Sign with a finger or stylus. The signature and today's date are placed on the acceptance line, and the
        document is locked against silent edits.
      </div>
      <canvas
        ref={ref} width={800} height={300}
        onMouseDown={start} onMouseMove={move} onMouseUp={end} onMouseLeave={end}
        onTouchStart={start} onTouchMove={move} onTouchEnd={end}
        style={{
          width: "100%", height: 190, border: `1.5px dashed ${S.line}`, borderRadius: 12,
          touchAction: "none", background: "#fff", display: "block",
        }}
      />
    </Sheet>
  );
}

/* ================================================================
   LOGIN
   ================================================================ */
/* ==================================================================
   Marketing — the public site. Not a copy of any competitor's layout;
   the section order (hero, feature-by-feature with real screenshots,
   values, pricing, final CTA) is the standard shape most SaaS sites
   converge on for good reason, filled in with RoofStride's own
   content and its own actual screenshots — no stock photography, no
   fabricated mockups.
   ================================================================== */
const MKT = { ink: "#20242A", teal: "#0A9E98", tealDark: "#087F7A", sub: "#5B6470", bg: "#F7F8FA", line: "#E5E7EB" };
const MKT_DISPLAY_FONT = "'Space Grotesk', 'Inter', -apple-system, sans-serif";

/* Loads Space Grotesk once, on the marketing page only — the rest of
   the app stays on the system/Inter stack. A confident, geometric
   display face for headlines only (never body copy) is the one
   deliberate typographic choice on this page; everything else stays
   quiet so that choice reads, rather than fighting for attention with
   five other decisions. */
function useMktFont() {
  useEffect(() => {
    if (document.getElementById("mkt-font-link")) return;
    const link = document.createElement("link");
    link.id = "mkt-font-link";
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

/* ==================================================================
   Scroll-linked motion — the page's signature element. Not a one-shot
   fade-in-once-then-forget (that was the old Reveal): every section
   continuously tracks its own position in the viewport and answers to
   it the whole time it's on screen, the way apple.com's product pages
   do — content settles into full focus as it centers, and drifts back
   slightly as it leaves, so scrolling itself feels like the thing
   moving the page forward ("stride" literalized). A single imperative
   rAF-driven scroll listener drives every registered section by
   writing directly to element.style — not React state — because a
   piece of state per scroll pixel would re-render the whole page 60
   times a second. `prefers-reduced-motion` short-circuits to fully
   visible/static, honored at the hook level so no page consumer has
   to remember to check it.
   ================================================================== */
const MKT_MOTION = { els: new Set(), raf: null, reduced: false };

function mktMotionTick() {
  MKT_MOTION.raf = null;
  const vh = window.innerHeight;
  MKT_MOTION.els.forEach((el) => {
    const r = el.getBoundingClientRect();
    /* Entry and exit tracked from separate edges, not the element's
       own vertical center (a tall stacked mobile row can be taller
       than the viewport, so its own center never lines up with when
       the top content is actually visible — see the note this
       replaced, still true). But the first version of this fix had
       its own bug: `1 - r.top / (vh * K)` is mathematically anchored
       so entry only reaches 1 once r.top hits exactly 0 — the
       element's top edge at the very TOP of the screen — no matter
       what K is. That's much too late for a natural reveal: readers
       look at the middle of their screen, not the top edge, so
       content stayed dim through the whole time it was comfortably
       in view. Rewritten so entry reaches 1 once the top has scrolled
       up to roughly the vertical middle of the viewport, not the
       very top — full brightness while it's still centered on
       screen, the way it actually reads as "revealed." */
    const entryDoneAt = vh * 0.5;   // top edge at the viewport's middle = fully revealed
    let entry = (vh - r.top) / (vh - entryDoneAt);
    entry = Math.max(0, Math.min(1, entry));
    let exit = 1 - r.bottom / (vh * 0.35);
    exit = Math.max(0, Math.min(1, exit));
    const eased = entry * (1 - exit * 0.4);
    const rise = (1 - entry) * (el.dataset.mktY ? +el.dataset.mktY : 60);
    const scale = 0.86 + eased * 0.14;
    el.style.opacity = String(0.08 + eased * 0.92);
    el.style.transform = `translateY(${rise}px) scale(${scale})`;
    if (el.dataset.mktParallax) {
      const depth = +el.dataset.mktParallax;
      el.style.setProperty("--mkt-parallax", `${(0.5 - entry) * depth}px`);
    }
  });
}
function mktMotionSchedule() {
  if (MKT_MOTION.raf != null) return;
  if (typeof requestAnimationFrame === "function") {
    MKT_MOTION.raf = requestAnimationFrame(mktMotionTick);
  } else {
    MKT_MOTION.raf = setTimeout(mktMotionTick, 16);
  }
}
if (typeof window !== "undefined" && typeof window.addEventListener === "function") {
  window.addEventListener("scroll", mktMotionSchedule, { passive: true });
  window.addEventListener("resize", mktMotionSchedule, { passive: true });
  if (window.matchMedia) {
    try { MKT_MOTION.reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches; }
    catch { /* some test/embed environments don't implement matchMedia fully */ }
  }
}

function Reveal({ children, delay = 0, y = 60, parallax, style, className, id }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el || MKT_MOTION.reduced) return;
    el.dataset.mktY = String(y);
    if (parallax) el.dataset.mktParallax = String(parallax);
    /* Deliberately NO CSS transition on opacity/transform here. This is
       the actual bug that made the whole system read as "not really
       happening": a transition fights a value that's already being
       recalculated every animation frame during a scroll — each new
       target arrives before the last one finishes easing toward it, so
       the motion perpetually lags and chases instead of tracking the
       scroll gesture directly. A true scroll-SCRUBBED effect (this is
       how Apple's own product pages, and libraries like GSAP
       ScrollTrigger in scrub mode, actually do it) maps scroll position
       to style values 1:1 with no easing layered on top — the rAF loop
       itself is what already makes it smooth. */
    el.style.transition = "none";
    MKT_MOTION.els.add(el);
    mktMotionSchedule();
    return () => { MKT_MOTION.els.delete(el); };
  }, [y, parallax, delay]);
  return (
    <div ref={ref} className={className ? `mkt-reveal ${className}` : "mkt-reveal"} id={id} style={{
      willChange: "opacity, transform", ...style,
    }}>{children}</div>
  );
}

function MktNav({ onSignIn, onStartTrial }) {
  return (
    <div style={{
      position: "sticky", top: 0, zIndex: 40, background: "rgba(255,255,255,.92)",
      backdropFilter: "blur(8px)", borderBottom: `1px solid ${MKT.line}`,
    }}>
      <div style={{
        maxWidth: 1100, margin: "0 auto", padding: "14px 20px",
        display: "flex", alignItems: "center", justifyContent: "space-between",
      }}>
        <img src="/roofstride-logo-horizontal.png" alt={PRODUCT.name} style={{ height: 28, display: "block" }} />
        <div style={{ display: "flex", alignItems: "center", gap: 18 }}>
          <button onClick={onSignIn} style={{
            border: "none", background: "none", color: MKT.ink, fontWeight: 600,
            fontSize: 14, cursor: "pointer", fontFamily: "inherit", padding: "8px 4px",
          }}>Sign in</button>
          <button onClick={onStartTrial} style={{
            border: "none", background: MKT.teal, color: "#fff", fontWeight: 700,
            fontSize: 14, cursor: "pointer", fontFamily: "inherit", padding: "10px 18px",
            borderRadius: 9,
          }}>Start free trial</button>
        </div>
      </div>
    </div>
  );
}

function MktFeatureRow({ eyebrow, title, body, points, img, reverse, id }) {
  return (
    <Reveal id={id} className="mkt-row" style={{
      display: "flex", alignItems: "center", gap: 56, maxWidth: 1100, margin: "0 auto",
      padding: "64px 20px", flexDirection: reverse ? "row-reverse" : "row",
    }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, letterSpacing: 1.2, color: MKT.teal, marginBottom: 10, textTransform: "uppercase" }}>
          {eyebrow}
        </div>
        <div style={{ fontFamily: MKT_DISPLAY_FONT, fontSize: 30, fontWeight: 700, color: MKT.ink, lineHeight: 1.22, letterSpacing: -0.3, marginBottom: 14 }}>{title}</div>
        <div style={{ fontSize: 16, color: MKT.sub, lineHeight: 1.6, marginBottom: 18 }}>{body}</div>
        {points && (
          <div>
            {points.map((p, i) => (
              <div key={i} style={{ display: "flex", gap: 10, alignItems: "flex-start", padding: "6px 0" }}>
                <CheckCircle2 size={17} color={MKT.teal} style={{ flexShrink: 0, marginTop: 2 }} />
                <div style={{ fontSize: 14.5, color: MKT.ink }}>{p}</div>
              </div>
            ))}
          </div>
        )}
      </div>
      <div style={{ flexShrink: 0 }}>
        <img src={img} alt={title} style={{
          width: 260, borderRadius: 18, display: "block",
          boxShadow: "0 20px 50px rgba(32,36,42,.18)", border: `1px solid ${MKT.line}`,
        }} />
      </div>
    </Reveal>
  );
}

/* Smooth-scrolls to a same-page section by id — used by the footer's
   "Product" links and "Back to top", so they feel like real navigation
   without needing actual routes for a single-page marketing site. */
function scrollToMktSection(id) {
  if (typeof document === "undefined") return;
  const el = document.getElementById(id);
  if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
}

