/* ==================================================================
   ADMIN MASTER SWITCHES + AUDIT LOG

   Two related things. The switches decide what the company can see and
   do; the log records what was actually done. Both are admin-only, and
   the log deliberately cannot be exported — a record of who looked at
   what is exactly the sort of thing that should not leave with anyone.
================================================================== */
const FEATURE_SWITCHES = [
  ["portal", "Client portal", "Publish links, share documents, two-way messaging"],
  ["claim", "Insurance claims", "Claim tracking, supplements, carrier money"],
  ["changeorders", "Change orders", "Priced amendments after signing"],
  ["handoff", "Sold approval gate", "Require an admin to approve before production"],
  ["ventilation", "Ventilation calculator", "Net-free-area sizing and supplement wording"],
  ["reviews", "Review requests", "Automated review sequence after completion"],
  ["chat", "Team chat", "Company channel in the Inbox"],
  ["dispatch", "Dispatch board", "Crew-by-day scheduling"],
  ["codes", "Code lookup", "Jurisdiction requirements and citations"],
  ["companycam", "CompanyCam", "Create and open CompanyCam projects"],
];
const DEFAULT_FEATURES = FEATURE_SWITCHES.reduce((a, [k]) => { a[k] = true; return a; }, {});
function featureOn(features, key) {
  const merged = { ...DEFAULT_FEATURES, ...(features || {}) };
  return merged[key] !== false;
}

/* What counts as unusual. Deliberately conservative: the cost of a
   false positive is someone being signed out mid-job, which is worse
   than a slow leak. These catch bulk behaviour, not curiosity. */
const ANOMALY_RULES = [
  { id: "rapid_open", label: "Opened many jobs very quickly", window: 60000, count: 25,
    why: "Twenty-five jobs in a minute is scraping, not working." },
  { id: "export_attempts", label: "Repeated blocked export attempts", window: 300000, count: 3,
    why: "Three blocked exports in five minutes is someone testing the lock." },
  { id: "bulk_delete", label: "Bulk deletion", window: 300000, count: 8,
    why: "Eight deletions in five minutes is not routine tidying." },
];

function detectAnomaly(events, now) {
  /* events: [{ type, at }] with `at` as epoch ms. */
  for (const rule of ANOMALY_RULES) {
    const since = now - rule.window;
    const hits = events.filter((e) => e.at >= since && e.rule === rule.id).length;
    if (hits >= rule.count) return rule;
  }
  return null;
}

/* ==================================================================
   CLAIMS DASHBOARD — every open claim, company-wide.

   The per-job claim section answers "where is this one". This answers
   "what is the carrier sitting on across the whole book", which is the
   number that actually gets chased.
================================================================== */
function ClaimsDashboard({ jobs, onBack, onOpenJob, embedded = false }) {
  const [stage, setStage] = useState("all");
  const claims = jobs.filter((j) => j.claimType === "Insurance" && (j.claim || j.insurance));
  const rows = claims.map((j) => ({ j, m: claimMath(j), st: (j.claim || {}).stage || "filed" }));
  const shown = stage === "all" ? rows : rows.filter((r) => r.st === stage);

  const owed = rows.reduce((a, r) => a + r.m.owedByCarrier, 0);
  const dep = rows.reduce((a, r) => a + r.m.depOutstanding, 0);
  const sup = rows.reduce((a, r) => a + r.m.supOutstanding, 0);
  const acv = rows.reduce((a, r) => a + r.m.acvReceived, 0);
  const deduct = rows.reduce((a, r) => a + Math.max(0, r.m.deductible - r.m.deductibleCollected), 0);
  const unwaived = rows.filter((r) => r.m.deductible - r.m.deductibleCollected > 0).length;

  return (
    <div style={{ padding: embedded ? 0 : "20px 16px 110px", background: embedded ? "transparent" : S.bg, minHeight: embedded ? undefined : "100vh" }}>
      {!embedded && <SubHeader title="Claims" onBack={onBack} />}

      <Card style={{ marginTop: 14, borderLeft: `4px solid ${owed > 0 ? "#E8B931" : S.line}` }}>
        <div style={{ fontSize: 11.5, fontWeight: 800, letterSpacing: ".08em", color: S.sub }}>OWED BY CARRIERS</div>
        <div style={{ fontSize: 34, fontWeight: 800, color: owed > 0 ? "#9A6B00" : S.ink, marginTop: 4, lineHeight: 1.1 }}>
          {money(owed)}
        </div>
        <div style={{ fontSize: 12.5, color: S.sub, marginTop: 6, lineHeight: 1.5 }}>
          Across <b>{rows.length}</b> {rows.length === 1 ? "claim" : "claims"}. Depreciation
          releases on invoice; supplements release when the carrier approves them.
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 12, borderTop: `1px solid ${S.line}`, paddingTop: 12 }}>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".06em", color: S.sub }}>DEPRECIATION</div>
            <div style={{ fontSize: 17, fontWeight: 800, color: S.ink, marginTop: 2 }}>{money(dep)}</div>
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".06em", color: S.sub }}>SUPPLEMENTS</div>
            <div style={{ fontSize: 17, fontWeight: 800, color: S.ink, marginTop: 2 }}>{money(sup)}</div>
          </div>
        </div>
      </Card>

      <div style={{ display: "flex", gap: 10, marginTop: 12 }}>
        <Card style={{ flex: 1 }} pad={14}>
          <div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".06em", color: S.sub }}>ACV RELEASED</div>
          <div style={{ fontSize: 19, fontWeight: 800, color: S.ink, marginTop: 3 }}>{money(acv)}</div>
          <div style={{ fontSize: 11.5, color: S.sub, marginTop: 2 }}>already collected</div>
        </Card>
        <Card style={{ flex: 1 }} pad={14}>
          <div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".06em", color: S.sub }}>DEDUCTIBLES DUE</div>
          <div style={{ fontSize: 19, fontWeight: 800, color: deduct > 0 ? "#B3261E" : S.ink, marginTop: 3 }}>{money(deduct)}</div>
          <div style={{ fontSize: 11.5, color: S.sub, marginTop: 2 }}>{unwaived} uncollected</div>
        </Card>
      </div>

      <div style={{ display: "flex", gap: 6, overflowX: "auto", margin: "14px 0 4px", paddingBottom: 2 }}>
        {[["all", "All"], ...CLAIM_STAGES.map(([id, label]) => [id, label])].map(([id, label]) => {
          const n = id === "all" ? rows.length : rows.filter((r) => r.st === id).length;
          return (
            <button key={id} onClick={() => setStage(id)} style={{
              border: `1.5px solid ${stage === id ? T.accent : S.line}`,
              background: stage === id ? T.accentSoft : "#fff", color: stage === id ? T.accent : S.ink,
              borderRadius: 999, padding: "7px 12px", fontSize: 12.5, fontWeight: 700,
              cursor: "pointer", whiteSpace: "nowrap", fontFamily: "inherit",
            }}>{label} {n > 0 ? `· ${n}` : ""}</button>
          );
        })}
      </div>

      {shown.length === 0 && (
        <Card pad={18}><div style={{ fontSize: 13.5, color: S.sub }}>No claims in this stage.</div></Card>
      )}
      {shown.map(({ j, m, st }) => {
        const label = (CLAIM_STAGES.find(([id]) => id === st) || [st, st])[1];
        return (
          <Card key={j.id} style={{ marginTop: 10 }} pad={0}>
            <button onClick={() => onOpenJob(j.id, "claim")} style={{
              width: "100%", textAlign: "left", border: "none", background: "none",
              cursor: "pointer", padding: 15, fontFamily: "inherit",
            }}>
              <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "flex-start" }}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 15, fontWeight: 700, color: S.ink }}>{j.name}</div>
                  <div style={{ fontSize: 12, color: S.sub, marginTop: 2 }}>{j.address}</div>
                  <div style={{ fontSize: 12, color: S.sub, marginTop: 3 }}>
                    {(j.insurance || {}).carrier || "No carrier"}{(j.insurance || {}).claim ? ` · ${(j.insurance || {}).claim}` : ""}
                  </div>
                </div>
                <div style={{ textAlign: "right", flexShrink: 0 }}>
                  <Chip tone={st === "closed" ? "green" : "blue"}>{label}</Chip>
                  <div style={{ fontSize: 16, fontWeight: 800, color: m.owedByCarrier > 0 ? "#9A6B00" : S.sub, marginTop: 6 }}>
                    {money(m.owedByCarrier)}
                  </div>
                  <div style={{ fontSize: 10.5, color: S.sub }}>owed</div>
                </div>
              </div>
              {m.flags.length > 0 && (
                <div style={{ display: "flex", gap: 6, alignItems: "center", marginTop: 9, paddingTop: 9, borderTop: `1px solid ${S.line}` }}>
                  <AlertTriangle size={13} color="#9A6B00" style={{ flexShrink: 0 }} />
                  <span style={{ fontSize: 11.5, color: S.sub }}>
                    {m.flags.length} {m.flags.length === 1 ? "item needs" : "items need"} attention
                  </span>
                </div>
              )}
            </button>
          </Card>
        );
      })}
    </div>
  );
}

/* ==================================================================
   CREW PAYOUTS

   Cap-out covers what the rep earns. This covers what the crew is
   owed: contracted amount per job, what has been paid, what is still
   outstanding — the other half of labour cost.
================================================================== */
function CrewPayouts({ jobs, crews, onBack, onOpenJob, isAdmin }) {
  const [crewId, setCrewId] = useState("all");
  if (!isAdmin) {
    return (
      <div style={{ padding: "20px 16px 110px", background: S.bg, minHeight: "100vh" }}>
        <SubHeader title="Crew payouts" onBack={onBack} />
        <Card style={{ marginTop: 16 }}>
          <div style={{ fontSize: 14, color: S.sub }}>This screen is restricted to admins.</div>
        </Card>
      </div>
    );
  }
  /* A crew's labour on a job is whatever labour lines name them, or the
     whole labour bucket when the job is assigned to them and nothing is
     itemised. Payments out are the non-Received payment rows. */
  const rows = (crews || []).map((c) => {
    const mine = jobs.filter((j) => j.crewId === c.id);
    const contracted = mine.reduce((a, j) => {
      const lines = ((j.fin || {}).labor || []);
      const named = lines.filter((l) => String(l.by || "").toLowerCase().includes(String(c.name || "").toLowerCase()));
      return a + (named.length ? named : lines).reduce((x, l) => x + num(l.amt), 0);
    }, 0);
    const paid = mine.reduce((a, j) => a + (j.payments || [])
      .filter((p) => p.type !== "Received" && String(p.to || "").toLowerCase().includes(String(c.name || "").toLowerCase()))
      .reduce((x, p) => x + num(p.amt), 0), 0);
    return { crew: c, jobs: mine, contracted, paid, outstanding: Math.max(0, contracted - paid) };
  });
  const shown = crewId === "all" ? rows : rows.filter((r) => r.crew.id === crewId);
  const totalOut = rows.reduce((a, r) => a + r.outstanding, 0);

  return (
    <div style={{ padding: "20px 16px 110px", background: S.bg, minHeight: "100vh" }}>
      <SubHeader title="Crew payouts" onBack={onBack} />
      <Card style={{ marginTop: 14 }}>
        <div style={{ fontSize: 11.5, fontWeight: 800, letterSpacing: ".08em", color: S.sub }}>OWED TO CREWS</div>
        <div style={{ fontSize: 30, fontWeight: 800, color: totalOut > 0 ? "#9A6B00" : S.ink, marginTop: 4 }}>
          {money(totalOut)}
        </div>
        <div style={{ fontSize: 12.5, color: S.sub, marginTop: 6, lineHeight: 1.5 }}>
          Contracted labour less what has been paid out. Labour lines naming a
          crew count to that crew; otherwise the job's whole labour bucket does.
        </div>
      </Card>
      <div style={{ display: "flex", gap: 6, overflowX: "auto", margin: "14px 0 4px" }}>
        {[["all", "All crews"], ...(crews || []).map((c) => [c.id, c.name])].map(([id, label]) => (
          <button key={id} onClick={() => setCrewId(id)} style={{
            border: `1.5px solid ${crewId === id ? T.accent : S.line}`,
            background: crewId === id ? T.accentSoft : "#fff", color: crewId === id ? T.accent : S.ink,
            borderRadius: 999, padding: "7px 12px", fontSize: 12.5, fontWeight: 700,
            cursor: "pointer", whiteSpace: "nowrap", fontFamily: "inherit",
          }}>{label}</button>
        ))}
      </div>
      {shown.map((r) => (
        <Card key={r.crew.id} style={{ marginTop: 10 }}>
          <CardTitle right={<span style={{ fontWeight: 800, color: r.outstanding > 0 ? "#9A6B00" : S.sub }}>{money(r.outstanding)}</span>}>
            {r.crew.name}
          </CardTitle>
          <KV k="Contracted" v={money(r.contracted)} />
          <KV k="Paid" v={money(r.paid)} />
          <KV k="Outstanding" v={money(r.outstanding)} strong />
          {r.jobs.length === 0 && <div style={{ fontSize: 12.5, color: S.sub, marginTop: 6 }}>No jobs assigned.</div>}
          {r.jobs.slice(0, 6).map((j) => (
            <button key={j.id} onClick={() => onOpenJob(j.id)} style={{
              display: "flex", justifyContent: "space-between", width: "100%", textAlign: "left",
              border: "none", background: "none", cursor: "pointer", padding: "7px 0",
              borderTop: `1px solid ${S.line}`, fontFamily: "inherit",
            }}>
              <span style={{ fontSize: 13, color: S.ink }}>{j.name}</span>
              <span style={{ fontSize: 12, color: S.sub }}>{j.schedDate || "unscheduled"}</span>
            </button>
          ))}
        </Card>
      ))}
    </div>
  );
}

function AdminControls({ features, setFeatures, activity, users, currentUser, onBack, toast, security, setSecurity }) {
  const admin = !!(currentUser && currentUser.role === "admin");
  const [tab, setTab] = useState("features");
  const [q, setQ] = useState("");
  if (!admin) {
    return (
      <div style={{ padding: "20px 16px 110px", background: S.bg, minHeight: "100vh" }}>
        <SubHeader title="Admin controls" onBack={onBack} />
        <Card style={{ marginTop: 16 }}>
          <div style={{ fontSize: 14, color: S.sub }}>This screen is restricted to admins.</div>
        </Card>
      </div>
    );
  }
  const feats = { ...DEFAULT_FEATURES, ...(features || {}) };
  const sec = security || {};
  const needle = q.trim().toLowerCase();
  const log = (activity || []).filter((a) => !needle
    || String(a.text || "").toLowerCase().includes(needle)
    || String(a.by || "").toLowerCase().includes(needle));

  return (
    <div style={{ padding: "20px 16px 110px", background: S.bg, minHeight: "100vh" }}>
      <SubHeader title="Admin controls" onBack={onBack} />
      <div style={{ display: "flex", gap: 8, margin: "14px 0" }}>
        {[["features", "Features"], ["security", "Security"], ["log", "Audit log"]].map(([id, label]) => (
          <button key={id} onClick={() => setTab(id)} style={{
            flex: 1, border: `1.5px solid ${tab === id ? T.accent : S.line}`,
            background: tab === id ? T.accentSoft : "#fff", color: tab === id ? T.accent : S.ink,
            borderRadius: 999, padding: "9px 10px", fontSize: 13, fontWeight: 800, cursor: "pointer",
          }}>{label}</button>
        ))}
      </div>

      {tab === "features" && (
        <Card>
          <CardTitle>What the company can use</CardTitle>
          <div style={{ fontSize: 12.5, color: S.sub, lineHeight: 1.5, marginBottom: 6 }}>
            Turning something off hides it for everyone, including other
            admins. Existing data is kept — switch it back on and it returns.
          </div>
          {FEATURE_SWITCHES.map(([key, label, sub]) => (
            <div key={key} style={{ display: "flex", alignItems: "center", gap: 12, padding: "11px 0", borderTop: `1px solid ${S.line}` }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 14, fontWeight: 600, color: feats[key] === false ? S.sub : S.ink }}>{label}</div>
                <div style={{ fontSize: 11.5, color: S.sub, marginTop: 1 }}>{sub}</div>
              </div>
              <Toggle on={feats[key] !== false} onClick={() => setFeatures({ ...feats, [key]: feats[key] === false })} />
            </div>
          ))}
        </Card>
      )}

      {tab === "security" && (
        <>
          <Card>
            <CardTitle>Data protection</CardTitle>
            <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "11px 0", borderTop: `1px solid ${S.line}` }}>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 14, fontWeight: 600 }}>Block reps from exporting</div>
                <div style={{ fontSize: 11.5, color: S.sub, marginTop: 1, lineHeight: 1.45 }}>
                  Already on. Reps cannot download CSVs of jobs, commission or
                  contacts; every attempt is logged.
                </div>
              </div>
              <Chip tone="green">On</Chip>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "11px 0", borderTop: `1px solid ${S.line}` }}>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 14, fontWeight: 600 }}>Sign out on unusual activity</div>
                <div style={{ fontSize: 11.5, color: S.sub, marginTop: 1, lineHeight: 1.45 }}>
                  Ends the session when someone behaves like they are harvesting
                  rather than working.
                </div>
              </div>
              <Toggle on={sec.anomalyLogout !== false}
                onClick={() => setSecurity({ ...sec, anomalyLogout: sec.anomalyLogout === false })} />
            </div>
          </Card>
          <Card style={{ marginTop: 12 }}>
            <CardTitle>What triggers a sign-out</CardTitle>
            {ANOMALY_RULES.map((r) => (
              <div key={r.id} style={{ padding: "9px 0", borderTop: `1px solid ${S.line}` }}>
                <div style={{ fontSize: 13.5, fontWeight: 600, color: S.ink }}>{r.label}</div>
                <div style={{ fontSize: 11.5, color: S.sub, marginTop: 2, lineHeight: 1.45 }}>
                  {r.count} in {Math.round(r.window / 60000)} {r.window === 60000 ? "minute" : "minutes"} — {r.why}
                </div>
              </div>
            ))}
            <Callout label="What this does and does not do" tone="amber">
              This raises the cost of bulk-harvesting your data. It cannot stop
              someone reading their own screen or photographing it, and it is
              not a substitute for a signed agreement about who owns the book
              of business. Treat it as a tripwire, not a lock.
            </Callout>
          </Card>
        </>
      )}

      {tab === "log" && (
        <Card>
          <CardTitle right={<Chip tone="gray">{log.length}</Chip>}>Audit log</CardTitle>
          <input style={{ ...inputStyle, marginBottom: 10 }} value={q} onChange={(e) => setQ(e.target.value)}
            placeholder="Search by person or action" />
          <div style={{ fontSize: 11.5, color: S.sub, marginBottom: 8, lineHeight: 1.5 }}>
            Deliberately not exportable — a record of who looked at what should
            not be the easiest thing in the building to walk out with.
          </div>
          {log.length === 0 && <div style={{ fontSize: 13.5, color: S.sub }}>Nothing matches.</div>}
          {log.slice(0, 200).map((a, i2) => {
            const flagged = /deleted|export|blocked/i.test(String(a.text || "") + String(a.type || ""));
            return (
              <div key={a.id || i2} style={{
                padding: "9px 0", borderTop: `1px solid ${S.line}`,
                background: flagged ? "#FFF6E5" : "transparent",
              }}>
                <div style={{ fontSize: 11.5, color: S.sub }}>{a.at} · {a.by}</div>
                <div style={{ fontSize: 13.5, color: S.ink, marginTop: 2, lineHeight: 1.45 }}>{a.text}</div>
              </div>
            );
          })}
        </Card>
      )}
    </div>
  );
}

function SetupKeys({ apiSetup, setApiSetup, currentUser, onBack, toast }) {
  const admin = !!(currentUser && currentUser.role === "admin");
  const [openId, setOpenId] = useState(null);
  if (!admin) {
    return (
      <div style={{ padding: "20px 16px 110px", background: S.bg, minHeight: "100vh" }}>
        <SubHeader title="Setup & keys" onBack={onBack} />
        <Card style={{ marginTop: 16 }}>
          <div style={{ fontSize: 14, color: S.sub }}>
            This screen is restricted to admins.
          </div>
        </Card>
      </div>
    );
  }
  const st = apiSetup || {};
  const statusOf = (it) => (it.doneByDefault && st[it.id] === undefined ? "done" : st[it.id] || "todo");
  const setStatus = (id, v) => setApiSetup({ ...st, [id]: v });
  const setConfig = (k, v) => setApiSetup({ ...st, config: { ...(st.config || {}), [k]: v } });
  const remaining = SETUP_ITEMS.filter((it) => statusOf(it) !== "done").length;

  return (
    <div style={{ padding: "20px 16px 110px", background: S.bg, minHeight: "100vh" }}>
      <SubHeader title="Setup & keys" onBack={onBack} />
      <Card style={{ marginTop: 16 }}>
        <div style={{ fontSize: 14, fontWeight: 700, color: S.ink }}>
          {remaining === 0 ? "Everything is connected." : remaining + " still to connect"}
        </div>
        <div style={{ fontSize: 12.5, color: S.sub, marginTop: 6, lineHeight: 1.5 }}>
          Secrets are never typed into this app. RoofStride runs in the browser
          with a public key, so anything saved here would be readable by every
          seat. Each card tells you the exact dashboard and variable name
          instead.
        </div>
      </Card>

      {SETUP_ITEMS.map((it) => {
        const stt = statusOf(it);
        const open = openId === it.id;
        return (
          <Card key={it.id} style={{ marginTop: 12 }} pad={0}>
            <button onClick={() => setOpenId(open ? null : it.id)} style={{
              display: "flex", alignItems: "center", gap: 12, width: "100%",
              border: "none", background: "none", cursor: "pointer", textAlign: "left", padding: 16,
            }}>
              <span style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 14.5, fontWeight: 700, color: S.ink }}>{it.label}</div>
                <div style={{ fontSize: 11.5, color: S.sub, marginTop: 2 }}>{it.unlocks}</div>
              </span>
              <Chip tone={stt === "done" ? "green" : stt === "doing" ? "blue" : "gray"}>
                {stt === "done" ? "Done" : stt === "doing" ? "In progress" : "To do"}
              </Chip>
            </button>
            {open && (
              <div style={{ padding: "0 16px 16px", borderTop: `1px solid ${S.line}` }}>
                <div style={{ fontSize: 12.5, color: S.sub, margin: "12px 0 4px" }}>Where it goes</div>
                <div style={{ fontSize: 13.5, fontWeight: 600, color: S.ink }}>{it.where}</div>
                <div style={{ fontSize: 12.5, color: S.sub, marginTop: 8 }}>Variable name</div>
                <div style={{
                  fontSize: 12.5, fontFamily: "ui-monospace, monospace", color: S.ink,
                  background: S.soft, borderRadius: 8, padding: "8px 10px", marginTop: 4, wordBreak: "break-all",
                }}>{it.keyName}</div>
                <div style={{ fontSize: 12.5, color: S.sub, margin: "14px 0 6px" }}>Steps</div>
                <ol style={{ margin: 0, paddingLeft: 18, fontSize: 13, color: S.ink, lineHeight: 1.65 }}>
                  {it.steps.map((x, i) => <li key={i}>{x}</li>)}
                </ol>
                {it.note && (
                  <div style={{
                    fontSize: 12.5, color: S.ink, background: "#FFF6E5", border: "1px solid #F0D9A8",
                    borderRadius: 8, padding: "9px 11px", marginTop: 12, lineHeight: 1.5,
                  }}>{it.note}</div>
                )}
                {(it.config || []).map(([k, label, ph]) => (
                  <div key={k} style={{ marginTop: 12 }}>
                    <Field label={label} hint="Not a secret — safe to store.">
                      <input style={inputStyle} placeholder={ph}
                        value={(st.config || {})[k] || ""}
                        onChange={(e) => setConfig(k, e.target.value)} />
                    </Field>
                  </div>
                ))}
                <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
                  <Btn small kind={stt === "doing" ? "primary" : "ghost"}
                    onClick={() => { setStatus(it.id, "doing"); toast && toast("Marked in progress"); }}>In progress</Btn>
                  <Btn small kind={stt === "done" ? "primary" : "ghost"}
                    onClick={() => { setStatus(it.id, "done"); toast && toast("Marked done"); }}>Done</Btn>
                  <Btn small kind="ghost" onClick={() => setStatus(it.id, "todo")}>Reset</Btn>
                </div>
              </div>
            )}
          </Card>
        );
      })}
    </div>
  );
}

/* ==================================================================
   Help desk — every screen in the app, explained.

   Written as data rather than JSX so it is searchable: the search box
   matches title, summary, and body across every article at once,
   which is how someone actually looks for help ("where do I change
   commission?") rather than browsing a tree.
   ================================================================== */
